contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newOwner) public payable {
        require(newOwner != address(0));
        bool reverted;
        try c.transferOwnership(newOwner) { reverted = false; } catch { reverted = true; }
        address current = c.owner();
        assert(reverted || current == newOwner);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newOwner) public payable {
        address before = c.owner();
        bool reverted;
        try c.transferOwnership(newOwner) { reverted = false; } catch { reverted = true; }
        address afterOwner = c.owner();
        assert(c.owner() != address(this) ? (reverted && afterOwner == before) : (!reverted && afterOwner == newOwner));
    }
    receive() external payable {}
}
